-- ZUP-19: a pending address keeps its old link for the rest of its 48 hours.
UPDATE "newsletter_subscribers" SET "confirm_token" = "token", "confirm_sent_at" = "consent_at" WHERE "status" = 'pending';--> statement-breakpoint
