-- The footer and the signup form link /zasebnost; Nastavitve → Stran z izjavo o zasebnosti points at it unless set.
UPDATE "content" SET "data" = "data" || jsonb_build_object('privacyPage', jsonb_build_object('_type', 'reference', '_ref', (SELECT "id" FROM "content" WHERE "type" = 'page' AND "slug" = 'zasebnost'))), "updated_at" = now()
WHERE "id" = 'settings' AND coalesce("data"->'privacyPage', 'null'::jsonb) = 'null'::jsonb AND EXISTS (SELECT 1 FROM "content" WHERE "type" = 'page' AND "slug" = 'zasebnost');
